import{_ as t,c as h,o as i,a2 as a}from"./chunks/framework.B7el9cAC.js";const e=JSON.parse('{"title":"Mục 6.4 – Luật An Ninh Mạng","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-6/6.4-luat-an-ninh-mang.md","filePath":"chuong-6/6.4-luat-an-ninh-mang.md","lastUpdated":1775336269000}'),g={name:"chuong-6/6.4-luat-an-ninh-mang.md"};function o(r,n,u,c,l,s){return i(),h("div",null,[...n[0]||(n[0]=[a('<h1 id="muc-6-4-–-luat-an-ninh-mang" tabindex="-1">Mục 6.4 – Luật An Ninh Mạng <a class="header-anchor" href="#muc-6-4-–-luat-an-ninh-mang" aria-label="Permalink to &quot;Mục 6.4 – Luật An Ninh Mạng&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p><strong>Tại sao cần có luật về an ninh mạng?</strong></p><p>Internet không phải là &quot;vùng đất không có luật&quot;. Mọi hành động bạn thực hiện trên mạng – đăng bài, bình luận, chia sẻ thông tin, hack vào hệ thống người khác – đều có thể bị điều chỉnh bởi pháp luật.</p><p>Trước năm 2019, Việt Nam chưa có luật riêng về an ninh mạng. Hậu quả: tội phạm mạng gia tăng, thông tin sai lệch lan tràn, dữ liệu người dùng bị xâm phạm mà không có chế tài rõ ràng.</p><p><strong>Luật An ninh mạng 2018</strong> ra đời để giải quyết những vấn đề đó – tạo ra hành lang pháp lý bảo vệ người dùng và xử lý các hành vi vi phạm trên không gian mạng.</p><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="luat-an-ninh-mang-la-gi" tabindex="-1">Luật An ninh mạng là gì? <a class="header-anchor" href="#luat-an-ninh-mang-la-gi" aria-label="Permalink to &quot;Luật An ninh mạng là gì?&quot;">​</a></h3><p><strong>Luật An ninh mạng số 24/2018/QH14</strong> được Quốc hội Việt Nam thông qua ngày 12/6/2018, có hiệu lực từ <strong>01/01/2019</strong>.</p><p>Luật này quy định về:</p><ul><li><strong>Bảo vệ an ninh quốc gia</strong> trên không gian mạng</li><li><strong>Đảm bảo trật tự, an toàn xã hội</strong> trên internet</li><li><strong>Quyền và nghĩa vụ</strong> của tổ chức, cá nhân sử dụng internet tại Việt Nam</li><li><strong>Biện pháp xử lý</strong> các vi phạm an ninh mạng</li></ul><h3 id="cac-hanh-vi-bi-nghiem-cam-theo-luat-an-ninh-mang" tabindex="-1">Các hành vi bị nghiêm cấm theo Luật An ninh mạng <a class="header-anchor" href="#cac-hanh-vi-bi-nghiem-cam-theo-luat-an-ninh-mang" aria-label="Permalink to &quot;Các hành vi bị nghiêm cấm theo Luật An ninh mạng&quot;">​</a></h3><p><strong>Nhóm 1 – Chống phá Nhà nước:</strong></p><ul><li>Đăng thông tin xuyên tạc, phủ nhận thành quả cách mạng</li><li>Kêu gọi, kích động lật đổ chính quyền</li><li>Tuyên truyền chiến tranh, chia rẽ khối đại đoàn kết dân tộc</li></ul><p><strong>Nhóm 2 – Gây hại cho cá nhân và xã hội:</strong></p><ul><li>Đăng thông tin <strong>sai sự thật</strong> gây hoang mang, ảnh hưởng trật tự xã hội</li><li><strong>Xúc phạm danh dự, nhân phẩm</strong> người khác trên mạng</li><li>Chia sẻ <strong>thông tin cá nhân</strong> của người khác khi chưa được phép</li><li><strong>Tống tiền, lừa đảo</strong> qua mạng</li><li>Phát tán <strong>nội dung khiêu dâm</strong>, đặc biệt liên quan đến trẻ em</li></ul><p><strong>Nhóm 3 – Tấn công hệ thống:</strong></p><ul><li><strong>Tấn công mạng</strong> (hack, DDoS) vào hệ thống thông tin</li><li>Phát tán <strong>phần mềm độc hại</strong> (malware, ransomware)</li><li>Chiếm đoạt <strong>tài khoản</strong> người khác trái phép</li><li><strong>Gián điệp mạng</strong> – đánh cắp thông tin bí mật nhà nước</li></ul><h3 id="cac-quy-đinh-quan-trong-voi-nguoi-dung-thong-thuong" tabindex="-1">Các quy định quan trọng với người dùng thông thường <a class="header-anchor" href="#cac-quy-đinh-quan-trong-voi-nguoi-dung-thong-thuong" aria-label="Permalink to &quot;Các quy định quan trọng với người dùng thông thường&quot;">​</a></h3><p><strong>Điều 8 – Nghiêm cấm:</strong></p><ul><li>Không được đăng thông tin sai sự thật</li><li>Không xúc phạm, vu khống người khác</li><li>Không chia sẻ ảnh/video riêng tư của người khác khi chưa được phép</li></ul><p><strong>Điều 16 – Phòng ngừa, xử lý thông tin trên mạng:</strong></p><ul><li>Các nền tảng mạng xã hội (Facebook, TikTok, YouTube) phải <strong>xóa nội dung vi phạm</strong> khi được yêu cầu trong vòng <strong>24 giờ</strong> (48 giờ với trường hợp khẩn cấp)</li><li>Phải <strong>lưu trữ dữ liệu</strong> người dùng Việt Nam tại Việt Nam (yêu cầu lưu trữ dữ liệu nội địa)</li></ul><h3 id="nghi-đinh-xu-phat" tabindex="-1">Nghị định xử phạt <a class="header-anchor" href="#nghi-đinh-xu-phat" aria-label="Permalink to &quot;Nghị định xử phạt&quot;">​</a></h3><p><strong>Nghị định 15/2020/NĐ-CP</strong> (thay bằng <strong>Nghị định 14/2022/NĐ-CP</strong>) quy định mức phạt:</p><table tabindex="0"><thead><tr><th>Hành vi</th><th>Mức phạt</th></tr></thead><tbody><tr><td>Đăng thông tin sai sự thật</td><td>10 – 20 triệu đồng</td></tr><tr><td>Xúc phạm danh dự người khác trên mạng</td><td>20 – 30 triệu đồng</td></tr><tr><td>Chia sẻ thông tin riêng tư khi chưa được phép</td><td>10 – 20 triệu đồng</td></tr><tr><td>Hack tài khoản mạng xã hội</td><td>10 – 20 triệu đồng</td></tr><tr><td>Tấn công hệ thống thông tin</td><td>Hình sự – tù giam</td></tr></tbody></table><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><p><strong>Tại sao cần luật an ninh mạng?</strong></p><p>Hãy so sánh với cuộc sống ngoài đời:</p><table tabindex="0"><thead><tr><th>Ngoài đời thực</th><th>Trên mạng (tương đương)</th></tr></thead><tbody><tr><td>Tung tin đồn thất thiệt có thể bị kiện</td><td>Đăng thông tin sai trên Facebook có thể bị phạt</td></tr><tr><td>Xúc phạm người khác trước đám đông = tội danh dự</td><td>Bình luận nhục mạ trên mạng = vi phạm pháp luật</td></tr><tr><td>Trộm cắp bị bắt giam</td><td>Hack tài khoản bị xử hình sự</td></tr><tr><td>Giả mạo giấy tờ là tội hình sự</td><td>Giả mạo tài khoản online cũng là tội hình sự</td></tr></tbody></table><p><strong>Điểm khác biệt:</strong> Trên mạng, tốc độ lan truyền nhanh hơn hàng nghìn lần → hậu quả có thể lớn hơn nhiều so với hành vi tương đương ngoài đời.</p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="quy-trinh-xu-ly-khi-phat-hien-vi-pham-an-ninh-mang" tabindex="-1">Quy trình xử lý khi phát hiện vi phạm an ninh mạng: <a class="header-anchor" href="#quy-trinh-xu-ly-khi-phat-hien-vi-pham-an-ninh-mang" aria-label="Permalink to &quot;Quy trình xử lý khi phát hiện vi phạm an ninh mạng:&quot;">​</a></h3><ol><li><strong>Người dùng báo cáo</strong> → Report nội dung vi phạm lên nền tảng (Facebook, TikTok...)</li><li><strong>Nền tảng xem xét</strong> → Trong 24 giờ phải có phản hồi (theo luật)</li><li><strong>Nếu vi phạm nghiêm trọng</strong> → Nền tảng gỡ bỏ hoặc khóa tài khoản</li><li><strong>Cơ quan chức năng vào cuộc</strong> → Cục An ninh mạng (Bộ Công an) điều tra</li><li><strong>Xác định danh tính</strong> → Qua IP, thông tin tài khoản, dữ liệu từ nền tảng</li><li><strong>Xử lý hành chính hoặc hình sự</strong> → Tùy mức độ vi phạm</li></ol><h3 id="khi-ban-la-nan-nhan-cua-vi-pham-tren-mang" tabindex="-1">Khi bạn là nạn nhân của vi phạm trên mạng: <a class="header-anchor" href="#khi-ban-la-nan-nhan-cua-vi-pham-tren-mang" aria-label="Permalink to &quot;Khi bạn là nạn nhân của vi phạm trên mạng:&quot;">​</a></h3><ol><li><strong>Lưu bằng chứng</strong> → Chụp màn hình, lưu URL, ghi thời gian</li><li><strong>Report trên nền tảng</strong> → Dùng tính năng báo cáo của mạng xã hội</li><li><strong>Gửi đơn lên Cục An toàn thông tin</strong> (Bộ TT&amp;TT) hoặc <strong>Cục An ninh mạng</strong> (Bộ Công an)</li><li><strong>Tố cáo tại Công an phường/xã</strong> nếu bị xúc phạm, vu khống, tống tiền</li><li><strong>Nhờ luật sư</strong> nếu thiệt hại lớn để khởi kiện dân sự đòi bồi thường</li></ol><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-vi-pham-đang-tin-sai-su-that" tabindex="-1">Ví dụ 1 – Cơ bản: Vi phạm đăng tin sai sự thật <a class="header-anchor" href="#vi-du-1-–-co-ban-vi-pham-đang-tin-sai-su-that" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Vi phạm đăng tin sai sự thật&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn H. đăng lên Facebook: &quot;Trường THPT X vừa có học sinh tử vong vì tai nạn trong giờ thể dục&quot; – thực ra là tin đồn hoàn toàn bịa đặt.</p><p><strong>Hậu quả pháp lý:</strong></p><ul><li>Vi phạm Điều 8 Luật An ninh mạng: Đăng thông tin sai sự thật gây hoang mang</li><li>Có thể bị phạt từ <strong>10 đến 20 triệu đồng</strong> theo Nghị định 14/2022</li><li>Nếu gây thiệt hại nghiêm trọng, có thể bị truy cứu trách nhiệm hình sự</li></ul><p><strong>Bài học:</strong> Trước khi chia sẻ tin tức, hãy kiểm tra từ <strong>ít nhất 2 nguồn uy tín</strong>. Nếu không chắc chắn, <strong>không đăng</strong>.</p><hr><h3 id="vi-du-2-–-thuc-te-xuc-pham-nguoi-khac-tren-mang-xa-hoi" tabindex="-1">Ví dụ 2 – Thực tế: Xúc phạm người khác trên mạng xã hội <a class="header-anchor" href="#vi-du-2-–-thuc-te-xuc-pham-nguoi-khac-tren-mang-xa-hoi" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Xúc phạm người khác trên mạng xã hội&quot;">​</a></h3><p><strong>Tình huống:</strong> Nhóm bạn bình luận xúc phạm, vu khống một bạn cùng lớp trên TikTok với lượng người xem lớn.</p><p><strong>Phân tích pháp lý:</strong></p><ul><li>Hành vi xúc phạm danh dự, nhân phẩm online = vi phạm <strong>Điều 8 Luật An ninh mạng</strong></li><li>Mức phạt: <strong>20-30 triệu đồng</strong> (hành chính)</li><li>Nếu gây hậu quả nghiêm trọng (nạn nhân trầm cảm, tự làm hại bản thân): có thể bị <strong>xử lý hình sự</strong> theo Bộ luật Hình sự</li></ul><p><strong>Điều quan trọng:</strong> Đây không chỉ là vấn đề đạo đức – đây là <strong>vi phạm pháp luật</strong> có thể bị truy tố.</p><hr><h3 id="vi-du-3-–-nang-cao-hack-tai-khoan-mang-xa-hoi" tabindex="-1">Ví dụ 3 – Nâng cao: Hack tài khoản mạng xã hội <a class="header-anchor" href="#vi-du-3-–-nang-cao-hack-tai-khoan-mang-xa-hoi" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: Hack tài khoản mạng xã hội&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn K. tự mình đoán được mật khẩu Facebook của bạn học và đăng nhập vào để xem tin nhắn riêng tư, không xóa hay sửa gì.</p><p><strong>Phân tích pháp lý:</strong></p><ul><li>Dù không gây &quot;thiệt hại vật chất&quot; rõ ràng, hành vi này vẫn là <strong>truy cập trái phép</strong> vào hệ thống thông tin</li><li>Vi phạm <strong>Điều 289 Bộ luật Hình sự 2015</strong> (sửa đổi 2017): Tội xâm nhập trái phép vào mạng máy tính</li><li>Mức phạt: phạt tiền <strong>50-300 triệu đồng</strong>, hoặc phạt tù <strong>từ 1-5 năm</strong></li></ul><p><strong>Bài học:</strong> Sự tò mò không là lý do biện hộ trước pháp luật. &quot;Tôi không làm hại gì&quot; không đồng nghĩa với &quot;tôi không vi phạm&quot;.</p><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="so-sanh-cac-muc-xu-ly-vi-pham-an-ninh-mang" tabindex="-1">So sánh các mức xử lý vi phạm an ninh mạng <a class="header-anchor" href="#so-sanh-cac-muc-xu-ly-vi-pham-an-ninh-mang" aria-label="Permalink to &quot;So sánh các mức xử lý vi phạm an ninh mạng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mức độ vi phạm</th><th>Hình thức xử lý</th><th>Ví dụ</th></tr></thead><tbody><tr><td>Nhẹ (lần đầu, ít ảnh hưởng)</td><td>Nhắc nhở, xóa nội dung</td><td>Đăng ảnh riêng tư của người khác</td></tr><tr><td>Trung bình</td><td>Phạt hành chính 10-30 triệu</td><td>Đăng tin sai sự thật lan rộng</td></tr><tr><td>Nặng</td><td>Phạt hành chính + tước quyền</td><td>Xúc phạm nghiêm trọng, ảnh hưởng lớn</td></tr><tr><td>Rất nặng</td><td>Truy cứu trách nhiệm hình sự</td><td>Hack hệ thống, tống tiền online</td></tr></tbody></table><h3 id="so-sanh-luat-an-ninh-mang-va-luat-an-toan-thong-tin-mang" tabindex="-1">So sánh Luật An ninh mạng và Luật An toàn thông tin mạng <a class="header-anchor" href="#so-sanh-luat-an-ninh-mang-va-luat-an-toan-thong-tin-mang" aria-label="Permalink to &quot;So sánh Luật An ninh mạng và Luật An toàn thông tin mạng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Luật An ninh mạng (2018)</th><th>Luật An toàn thông tin mạng (2015)</th></tr></thead><tbody><tr><td>Tập trung vào</td><td>An ninh quốc gia, trật tự xã hội</td><td>Bảo vệ thông tin, dữ liệu cá nhân</td></tr><tr><td>Đối tượng chính</td><td>Hành vi cá nhân, tổ chức</td><td>Hệ thống, dịch vụ, dữ liệu</td></tr><tr><td>Cơ quan thực thi</td><td>Bộ Công an</td><td>Bộ TT&amp;TT</td></tr><tr><td>Phạm vi</td><td>Rộng hơn</td><td>Hẹp hơn (kỹ thuật)</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>✅ <strong>Luật An ninh mạng</strong> số 24/2018/QH14, hiệu lực từ <strong>01/01/2019</strong></li><li>✅ Nghiêm cấm: đăng tin sai sự thật, xúc phạm người khác, hack hệ thống, tống tiền</li><li>✅ Phạt tin sai sự thật: <strong>10-20 triệu đồng</strong></li><li>✅ Phạt xúc phạm danh dự: <strong>20-30 triệu đồng</strong></li><li>✅ Hack hệ thống: có thể bị <strong>tù từ 1-5 năm</strong></li><li>✅ Nền tảng mạng xã hội phải xóa nội dung vi phạm trong <strong>24 giờ</strong></li><li>✅ Khi bị vi phạm: <strong>Lưu bằng chứng → Report → Tố cáo Công an</strong></li><li>✅ Ẩn danh <strong>không</strong> bảo vệ bạn khỏi pháp luật – IP và dữ liệu có thể truy ra</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-luat-an-ninh-mang-viet-nam-co-hieu-luc-tu-ngay-thang-nam-nao" tabindex="-1">Câu 1 (Dễ): Luật An ninh mạng Việt Nam có hiệu lực từ ngày tháng năm nào? <a class="header-anchor" href="#cau-1-de-luat-an-ninh-mang-viet-nam-co-hieu-luc-tu-ngay-thang-nam-nao" aria-label="Permalink to &quot;Câu 1 (Dễ): Luật An ninh mạng Việt Nam có hiệu lực từ ngày tháng năm nào?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> <strong>01/01/2019</strong> (Luật số 24/2018/QH14 được thông qua ngày 12/6/2018, có hiệu lực từ 01/01/2019)</p></blockquote><hr><h3 id="cau-2-de-hanh-vi-nao-sau-đay-vi-pham-luat-an-ninh-mang" tabindex="-1">Câu 2 (Dễ): Hành vi nào sau đây vi phạm Luật An ninh mạng? <a class="header-anchor" href="#cau-2-de-hanh-vi-nao-sau-đay-vi-pham-luat-an-ninh-mang" aria-label="Permalink to &quot;Câu 2 (Dễ): Hành vi nào sau đây vi phạm Luật An ninh mạng?&quot;">​</a></h3><p><strong>A.</strong> Chia sẻ bài học hay lên nhóm học tập<br><strong>B.</strong> Đăng thông tin sai sự thật về vụ tai nạn giao thông<br><strong>C.</strong> Bình luận tích cực dưới bài đăng của bạn bè<br><strong>D.</strong> Tạo tài khoản mạng xã hội với tên thật</p><blockquote><p><strong>Đáp án: B</strong> – Đăng thông tin sai sự thật vi phạm Điều 8 Luật An ninh mạng, có thể bị phạt 10-20 triệu đồng.</p></blockquote><hr><h3 id="cau-3-trung-binh-tai-sao-luat-an-ninh-mang-yeu-cau-cac-nen-tang-facebook-tiktok-phai-luu-tru-du-lieu-nguoi-dung-viet-nam-tai-viet-nam" tabindex="-1">Câu 3 (Trung bình): Tại sao Luật An ninh mạng yêu cầu các nền tảng (Facebook, TikTok...) phải lưu trữ dữ liệu người dùng Việt Nam tại Việt Nam? <a class="header-anchor" href="#cau-3-trung-binh-tai-sao-luat-an-ninh-mang-yeu-cau-cac-nen-tang-facebook-tiktok-phai-luu-tru-du-lieu-nguoi-dung-viet-nam-tai-viet-nam" aria-label="Permalink to &quot;Câu 3 (Trung bình): Tại sao Luật An ninh mạng yêu cầu các nền tảng (Facebook, TikTok...) phải lưu trữ dữ liệu người dùng Việt Nam tại Việt Nam?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Yêu cầu lưu trữ dữ liệu nội địa nhằm: (1) Giúp cơ quan chức năng VN có thể yêu cầu truy xuất dữ liệu khi điều tra tội phạm mà không cần qua cơ chế quốc tế phức tạp; (2) Bảo vệ dữ liệu người dùng VN khỏi bị truy cập tùy tiện từ nước ngoài; (3) Đảm bảo chủ quyền số quốc gia trên không gian mạng.</p></blockquote><hr><h3 id="cau-4-trung-binh-ban-thay-bai-đang-tren-mang-xa-hoi-chua-thong-tin-sai-su-that-co-the-gay-hoang-mang-ban-nen-lam-gi" tabindex="-1">Câu 4 (Trung bình): Bạn thấy bài đăng trên mạng xã hội chứa thông tin sai sự thật có thể gây hoang mang. Bạn nên làm gì? <a class="header-anchor" href="#cau-4-trung-binh-ban-thay-bai-đang-tren-mang-xa-hoi-chua-thong-tin-sai-su-that-co-the-gay-hoang-mang-ban-nen-lam-gi" aria-label="Permalink to &quot;Câu 4 (Trung bình): Bạn thấy bài đăng trên mạng xã hội chứa thông tin sai sự thật có thể gây hoang mang. Bạn nên làm gì?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> (1) <strong>Không chia sẻ</strong> bài đăng đó; (2) <strong>Report</strong> bài đăng lên nền tảng (Facebook, TikTok...) vì vi phạm quy định cộng đồng; (3) Nếu thấy nghiêm trọng, có thể <strong>tố cáo lên Cục An toàn thông tin</strong> (Bộ TT&amp;TT); (4) <strong>Đính chính</strong> thông tin bằng cách chia sẻ nguồn tin chính xác từ cơ quan nhà nước hoặc báo chí uy tín.</p></blockquote><hr><h3 id="cau-5-van-dung-mot-nguoi-đang-binh-luan-xuc-pham-nghiem-trong-ban-tren-mang-xa-hoi-va-bai-đang-nay-lan-rong-anh-huong-đen-danh-du-cua-ban-theo-luat-an-ninh-mang-quyen-loi-cua-ban-la-gi-va-ban-co-the-thuc-hien-nhung-buoc-nao" tabindex="-1">Câu 5 (Vận dụng): Một người đăng bình luận xúc phạm nghiêm trọng bạn trên mạng xã hội và bài đăng này lan rộng, ảnh hưởng đến danh dự của bạn. Theo Luật An ninh mạng, quyền lợi của bạn là gì và bạn có thể thực hiện những bước nào? <a class="header-anchor" href="#cau-5-van-dung-mot-nguoi-đang-binh-luan-xuc-pham-nghiem-trong-ban-tren-mang-xa-hoi-va-bai-đang-nay-lan-rong-anh-huong-đen-danh-du-cua-ban-theo-luat-an-ninh-mang-quyen-loi-cua-ban-la-gi-va-ban-co-the-thuc-hien-nhung-buoc-nao" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Một người đăng bình luận xúc phạm nghiêm trọng bạn trên mạng xã hội và bài đăng này lan rộng, ảnh hưởng đến danh dự của bạn. Theo Luật An ninh mạng, quyền lợi của bạn là gì và bạn có thể thực hiện những bước nào?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Theo Luật An ninh mạng và các quy định liên quan:</p><ul><li><strong>Quyền của bạn:</strong> Được bảo vệ danh dự, nhân phẩm; được yêu cầu xóa bỏ nội dung vi phạm; được bồi thường thiệt hại.</li><li><strong>Bước 1:</strong> Lưu bằng chứng (screenshot, URL, thời gian đăng).</li><li><strong>Bước 2:</strong> Report bài đăng lên nền tảng mạng xã hội để yêu cầu xóa trong 24 giờ.</li><li><strong>Bước 3:</strong> Tố cáo đến Công an phường/xã nơi cư trú, kèm bằng chứng.</li><li><strong>Bước 4:</strong> Cơ quan công an xác minh danh tính người vi phạm, có thể xử phạt hành chính 20-30 triệu hoặc truy tố hình sự nếu hậu quả nghiêm trọng.</li><li><strong>Bước 5:</strong> Nếu muốn bồi thường thiệt hại, có thể khởi kiện dân sự tại Tòa án.</li></ul></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Quan niệm sai</th><th>Thực tế đúng</th></tr></thead><tbody><tr><td>&quot;Đăng lên mạng không phải chịu trách nhiệm pháp lý&quot;</td><td>Luật An ninh mạng quy định rõ trách nhiệm pháp lý với mọi hành vi online</td></tr><tr><td>&quot;Dùng tài khoản ảo thì không ai biết là mình&quot;</td><td>IP, metadata và dữ liệu tài khoản có thể truy ra danh tính thật</td></tr><tr><td>&quot;Share lại tin người khác thì không phải lỗi của mình&quot;</td><td>Người chia sẻ tin sai cũng có thể bị xử phạt</td></tr><tr><td>&quot;Chỉ có nhà nước mới bị bảo vệ, cá nhân thì không&quot;</td><td>Luật bảo vệ cả cá nhân – xúc phạm cá nhân cũng bị phạt</td></tr><tr><td>&quot;Luật này chỉ áp dụng cho người lớn&quot;</td><td>Học sinh THPT cũng là công dân, cũng phải tuân theo pháp luật</td></tr><tr><td>&quot;Hack chỉ bị phạt nếu lấy tiền&quot;</td><td>Truy cập trái phép hệ thống (dù không lấy gì) vẫn là tội hình sự</td></tr></tbody></table>',88)])])}const d=t(g,[["render",o]]);export{e as __pageData,d as default};
